/**
 * Storno objednavky z detailu (2026). POST ?id=<uuid>, reason.
 *
 * Stav, castku k vraceni i uvolneni skladu resi novy e-shop (Order::cancel),
 * tady se nic nepocita – jen audit a mail zakaznikovi.
 */
public function cancelAction()
{
    global $db;
    legacy_db();
    auth_require('obchod');

    $id = get_param('id');
    $order = $db->one("SELECT * FROM orders WHERE id = '" . $id . "'");
    if ($order === null) {
        return $this->notFound('Objednávka ' . $id . ' neexistuje');
    }
    if (!is_post()) {
        return $this->redirect(admin_url('order', array('id' => $id)));
    }
    if ($order['status'] == 'cancelled') {
        flash('Objednávka už je stornovaná', 'error');

        return $this->detailAction();
    }

    $reason = trim((string) $this->post('reason'));
    if ($reason == '') {
        $reason = 'storno v administraci';
    }

    try {
        legacy_dispatch(new CancelOrder(OrderId::fromString($id), $reason));
    } catch (InvalidOrderStateTransitionException $e) {
        flash('Objednávku ve stavu „' . order_state_label($order['status']) . '“ nejde stornovat', 'error');

        return $this->detailAction();
    }

    $order = $db->one("SELECT * FROM orders WHERE id = '" . $id . "'");
    $refund = (int) $order['refund_amount_in_cents'];
    audit_log('order', $id, 'storno', array('reason' => $reason, 'refund' => $refund));

    $c = $db->one("SELECT email FROM customers WHERE id = '" . $order['customer_id'] . "'");
    if ($c && $c['email'] != '') {
        $body = "Dobrý den,\n\nvaše objednávka " . $id . " byla stornována.\n";
        if ($refund > 0) {
            $body .= "Zaplacenou částku " . format_price($refund, $order['refund_currency']) . " vám vrátíme.\n";
        }
        send_mail($c['email'], 'Objednávka byla stornována', $body);
    }

    cache_delete('dashboard_stats');

    return $this->redirect(admin_url('order', array('id' => $id)));
}

